type DeepStrings<T> = T extends string ? string : { readonly [K in keyof T]: DeepStrings<T[K]> };
type BaseAccessCatalog = DeepStrings<typeof english>;
export type AccessCatalog = Omit<BaseAccessCatalog, "auth" | "settings"> & {
  readonly auth: BaseAccessCatalog["auth"] & { readonly live: DeepStrings<typeof liveAuthTranslations.en> };
  readonly settings: BaseAccessCatalog["settings"] & DeepStrings<typeof accessPreferenceTranslations.en>;
};
export const VOICE_GUIDE_IDS = ["authPreview", "accessPreview", "keyboardGuide", "formErrors", "liveAuth", "authError", "otpTotp"] as const;
export type VoiceGuideId = (typeof VOICE_GUIDE_IDS)[number];

export function isVoiceGuideId(value: unknown): value is VoiceGuideId {
  return typeof value === "string" && (VOICE_GUIDE_IDS as readonly string[]).includes(value);
}

