export const languageCatalogs = Object.fromEntries(languageMetadata.map(({ code }) => {
  const base = baseLanguageCatalogs[code];
  return [code, {
    ...base,
    auth: { ...base.auth, live: liveAuthTranslations[code] },
    settings: { ...base.settings, ...accessPreferenceTranslations[code] },
  }];
})) as Record<LanguageCode, AccessCatalog>;

export function getVoiceGuideText(language: LanguageCode, id: VoiceGuideId): string {
  const previewGuides = languageCatalogs[language].voice.guides;
  if (Object.hasOwn(previewGuides, id)) {
    return languageCatalogs[language].voice.guides[id as keyof typeof english.voice.guides];
  }
  const liveGuides = liveAuthVoiceGuides[language];
  if (Object.hasOwn(liveGuides, id)) return liveGuides[id as keyof typeof liveAuthVoiceGuides.en];
  throw new Error("Unsupported voice guidance key");
}
